const sfResponse = $node['Fetch Salesforce Leads'].json;
const records = sfResponse.records || [];
const results = [];

const statusMap = { 'Open - Not Contacted': 'new', 'Working - Contacted': 'contacted', 'Closed - Converted': 'customer', 'Closed - Not Converted': 'lost' };

for (const lead of records) {
  results.push({ json: {
    email: lead.Email,
    first_name: lead.FirstName || '',
    last_name: lead.LastName || '',
    company: lead.Company || '',
    phone: lead.Phone || '',
    job_title: lead.Title || '',
    source: 'salesforce',
    external_id: lead.Id,
    lead_status: statusMap[lead.Status] || 'new'
  }});
}
return results;

const localContacts = $input.all().map(i => i.json);
if (!localContacts.length || !localContacts[0].id) return [];

const statusMap = { 'new': 'Open - Not Contacted', 'contacted': 'Working - Contacted', 'qualified': 'Working - Contacted', 'customer': 'Closed - Converted', 'lost': 'Closed - Not Converted' };

return localContacts.map(c => ({ json: {
  sf_id: c.external_id,
  email: c.email,
  FirstName: c.first_name,
  LastName: c.last_name || c.email.split('@')[0],
  Company: c.company || 'Unknown',
  Phone: c.phone,
  Status: statusMap[c.lead_status] || 'Open - Not Contacted',
  has_sf_id: !!c.external_id
}}));
